package addons

import (
	"fmt"
	"os"
	"path/filepath"
	"testing"

	"sigs.k8s.io/yaml"
)

const goldenHeader = `# GENERATED by internal/cluster/addons (render_test.go) from DefaultConfig().
# Do not edit by hand: run
#   UPDATE_GOLDEN=1 go -C apps/backend test ./internal/cluster/addons -run TestRenderedManifests
# The orchestrator applies the same object at runtime when
# ORCHESTRATOR_ENABLE_NETWORK_POLICY=true (mode %s).
`

// TestRenderedManifests keeps config/builds/*network-policy.yaml in sync with the generators.
func TestRenderedManifests(t *testing.T) {
	cfg := DefaultConfig()
	native, err := ToUnstructured(BuilderNetworkPolicy(cfg.Network))
	if err != nil {
		t.Fatal(err)
	}
	cases := map[string]struct {
		mode string
		obj  any
	}{
		"network-policy.yaml":        {"native", native.Object},
		"cilium-network-policy.yaml": {"cilium", CiliumBuilderPolicy(cfg.Network).Object},
	}
	dir := filepath.Join("..", "..", "..", "config", "builds")
	for file, c := range cases {
		body, err := yaml.Marshal(c.obj)
		if err != nil {
			t.Fatal(err)
		}
		want := []byte(sprintfHeader(c.mode) + "---\n" + string(body))
		path := filepath.Join(dir, file)
		if os.Getenv("UPDATE_GOLDEN") != "" {
			if err := os.MkdirAll(dir, 0o755); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(path, want, 0o644); err != nil {
				t.Fatal(err)
			}
			continue
		}
		got, err := os.ReadFile(path)
		if err != nil {
			t.Fatalf("%s: %v (run with UPDATE_GOLDEN=1)", path, err)
		}
		if string(got) != string(want) {
			t.Errorf("%s is out of date; run with UPDATE_GOLDEN=1", path)
		}
	}
}

func sprintfHeader(mode string) string { return fmt.Sprintf(goldenHeader, mode) }
